   374→// ─── Location URL Conversion (formerly location.ts) ──────────────────────────
   375→
   376→function decodePathPart(value: string): string {
   377→  try { return decodeURIComponent(value); } catch { return value; }
   378→}
   379→
   380→function extractWorkspacePageSlug(path: string): string | null {
   381→  const pageMatch = path.match(/^\/workspace\/([^/]+)\/page\/(.+)$/);
   382→  if (!pageMatch) return null;
   383→  return pageMatch[2].split("/").map(decodePathPart).join("/");
   384→}
   385→
   386→function extractLegacyPageSlug(rawPagePath: string | null): string | null {
   387→  if (!rawPagePath) return null;
   388→  const pagePath = decodePathPart(rawPagePath);
   389→  const match = pagePath.match(/^pages\/(.+)\/SKILL\.md$/);
   390→  if (match) return match[1];
   391→  if (pagePath.startsWith("pages/")) {
   392→    return pagePath.slice("pages/".length).replace(/\/SKILL\.md$/, "");
   393→  }
   394→  return null;
   395→}
   396→
   397→function normalizeSearch(search?: string): string {
   398→  if (!search) return "";
   399→  return search.startsWith("?") ? search : `?${search}`;
   400→}
   401→
   402→function normalizeHash(hash?: string): string {
   403→  if (!hash) return "";
   404→  return hash.startsWith("#") ? hash : `#${hash}`;
   405→}
   406→
   407→function appendUrlSuffix(path: string, location: LocationUrlSuffix): string {
   408→  const search = normalizeSearch(location.search);
   409→  const hash = normalizeHash(location.hash);
   410→  if (!search) return `${path}${hash}`;
   411→  if (path.includes("?")) return `${path}&${search.slice(1)}${hash}`;
   412→  return `${path}${search}${hash}`;
   413→}
   414→
   415→function buildDetailQuery(
   416→  workspacePath: string | undefined,
   417→  extraParams?: Record<string, string | undefined>
   418→): string {
   419→  const params = new URLSearchParams();
   420→  if (workspacePath) params.set("workspace_path", workspacePath);
   421→  if (extraParams) {
   422→    Object.entries(extraParams).forEach(([key, value]) => {
   423→      if (value) params.set(key, value);
   424→    });
   425→  }
   426→  const query = params.toString();
   427→  return query ? `?${query}` : "";
   428→}
   429→
   430→export function locationToUrl(location: DesktopLocation): string {
   431→  switch (location.kind) {
   432→    case "workspace-home":
   433→      return appendUrlSuffix(`/workspace/${encodeURIComponent(location.workspaceId)}`, location);
   434→    case "workspace-apps":
   435→      return appendUrlSuffix(`/workspace/${encodeURIComponent(location.workspaceId)}/apps`, location);
   436→    case "workspace-section":
   437→      return appendUrlSuffix(`/workspace/${encodeURIComponent(location.workspaceId)}/${location.section}`, location);
   438→    case "workspace-agent-detail":
   439→      return appendUrlSuffix(`/workspace/${encodeURIComponent(location.workspaceId)}/agent/${encodeURIComponent(location.agentId)}`, location);
   440→    case "workspace-executor-detail":
   441→      return appendUrlSuffix(`/workspace/${encodeURIComponent(location.workspaceId)}/executor/${encodeURIComponent(location.executorType)}`, location);
   442→    case "workspace-page": {
   443→      const encodedSlug = location.pageSlug.split("/").filter(Boolean).map((segment) => encodeURIComponent(segment)).join("/");
   444→      return appendUrlSuffix(`/workspace/${encodeURIComponent(location.workspaceId)}/page/${encodedSlug}`, location);
   445→    }
   446→    case "workspace-web": {
   447→      const params = new URLSearchParams({ url: location.url, title: location.title });
   448→      if (location.sourcePageSlug) params.set("source_page", location.sourcePageSlug);
   449→      if (location.webId) params.set("web_id", location.webId);
   450→      return appendUrlSuffix(`/workspace/${encodeURIComponent(location.workspaceId)}/web?${params.toString()}`, location);
   451→    }
   452→    case "agent-detail":
   453→      return appendUrlSuffix(`/agent/${encodeURIComponent(location.agentId)}${buildDetailQuery(location.workspacePath)}`, location);
   454→    case "executor-detail":
   455→      return appendUrlSuffix(`/executor/${encodeURIComponent(location.executorType)}${buildDetailQuery(location.workspacePath)}`, location);
   456→    case "skill-detail":
   457→      return appendUrlSuffix(`/skill/${encodeURIComponent(location.skillId)}${buildDetailQuery(location.workspacePath, { agent_id: location.agentId })}`, location);
   458→    case "mcp-server-detail":
   459→      return appendUrlSuffix(`/mcp-server/${encodeURIComponent(location.serverName)}${buildDetailQuery(location.workspacePath, { executor_type: location.executorType })}`, location);
   460→    case "subagent-detail":
   461→      return appendUrlSuffix(`/subagent/${encodeURIComponent(location.configId)}${buildDetailQuery(location.workspacePath, { executor_type: location.executorType })}`, location);
   462→    case "prompt-detail":
   463→      return appendUrlSuffix(`/prompt/${encodeURIComponent(location.promptId)}${buildDetailQuery(location.workspacePath, { executor_type: location.executorType })}`, location);
   464→    case "command-detail":
   465→      return appendUrlSuffix(`/command/${encodeURIComponent(location.commandId)}${buildDetailQuery(location.workspacePath, { executor_type: location.executorType })}`, location);
   466→    case "settings":
   467→      return appendUrlSuffix(location.section ? `/settings/${encodeURIComponent(location.section)}` : "/settings/general", location);
   468→    case "documents":
   469→      return appendUrlSuffix("/documents", location);
   470→    case "device-pair":
   471→      return appendUrlSuffix("/devices/pair", location);
   472→    case "global-route":
   473→      return location.path;
   474→    default: {
   475→      const exhaustive: never = location;
   476→      return exhaustive;
   477→    }
   478→  }
   479→}
   480→
   481→export function urlToLocation(url: string): DesktopLocation | null {
   482→  const parsed = new URL(url, "http://desktop.local");
   483→  const pathname = parsed.pathname;
   484→  const segments = pathname.split("/").filter(Boolean);
   485→  const suffix = { search: parsed.search || undefined, hash: parsed.hash || undefined };
   486→
   487→  if (pathname === "/documents") return { kind: "documents", ...suffix };
   488→  if (pathname === "/devices/pair") return { kind: "device-pair", ...suffix };
   489→  if (pathname === "/publish" || pathname === "/my-packages" || pathname === "/analytics") {
   490→    return { kind: "global-route", path: `${pathname}${parsed.search}${parsed.hash}` };
   491→  }
   492→
   493→  if (segments[0] === "settings") {
   494→    const section = normalizeSettingsSection(segments[1] ? decodePathPart(segments[1]) : "general");
   495→    return { kind: "settings", section, ...suffix };
   496→  }
   497→
   498→  if (segments[0] === "agent" && segments[1]) {
   499→    return { kind: "agent-detail", agentId: decodePathPart(segments[1]), workspacePath: parsed.searchParams.get("workspace_path") ?? undefined, hash: parsed.hash || undefined };
   500→  }
   501→  if (segments[0] === "executor" && segments[1]) {
   502→    return { kind: "executor-detail", executorType: decodePathPart(segments[1]), workspacePath: parsed.searchParams.get("workspace_path") ?? undefined, hash: parsed.hash || undefined };
   503→  }
   504→  if (segments[0] === "skill" && segments[1]) {
   505→    return { kind: "skill-detail", skillId: decodePathPart(segments[1]), agentId: parsed.searchParams.get("agent_id") ?? "", workspacePath: parsed.searchParams.get("workspace_path") ?? undefined, hash: parsed.hash || undefined };
   506→  }
   507→  if (segments[0] === "mcp-server" && segments[1]) {
   508→    return { kind: "mcp-server-detail", serverName: decodePathPart(segments[1]), executorType: parsed.searchParams.get("executor_type") ?? "CLAUDE_CODE", workspacePath: parsed.searchParams.get("workspace_path") ?? undefined, hash: parsed.hash || undefined };
   509→  }
   510→  if (segments[0] === "subagent" && segments[1]) {
   511→    return { kind: "subagent-detail", configId: decodePathPart(segments[1]), executorType: parsed.searchParams.get("executor_type") ?? "CLAUDE_CODE", workspacePath: parsed.searchParams.get("workspace_path") ?? undefined, hash: parsed.hash || undefined };
   512→  }
   513→  if (segments[0] === "prompt" && segments[1]) {
   514→    return { kind: "prompt-detail", promptId: decodePathPart(segments[1]), executorType: parsed.searchParams.get("executor_type") ?? "CLAUDE_CODE", workspacePath: parsed.searchParams.get("workspace_path") ?? undefined, hash: parsed.hash || undefined };
   515→  }
   516→  if (segments[0] === "command" && segments[1]) {
   517→    return { kind: "command-detail", commandId: decodePathPart(segments[1]), executorType: parsed.searchParams.get("executor_type") ?? "CLAUDE_CODE", workspacePath: parsed.searchParams.get("workspace_path") ?? undefined, hash: parsed.hash || undefined };
   518→  }
   519→
   520→  if (segments[0] === "workspace" && segments[1] === "page") {
   521→    const workspaceId = parsed.searchParams.get("workspace_id");
   522→    const pageSlug = extractLegacyPageSlug(parsed.searchParams.get("page_path"));
   523→    if (workspaceId && pageSlug) {
   524→      return { kind: "workspace-page", workspaceId, pageSlug, hash: parsed.hash || undefined };
   525→    }
   526→  }
   527→
   528→  if (segments[0] === "workspace" && segments[1]) {
   529→    const workspaceId = decodePathPart(segments[1]);
   530→    if (segments.length === 2) return { kind: "workspace-home", workspaceId, ...suffix };
   531→    if (segments[2] === "apps" && !segments[3]) return { kind: "workspace-apps", workspaceId, ...suffix };
   532→    if (segments[2] === "agents" && !segments[3]) return { kind: "workspace-section", workspaceId, section: "agent", ...suffix };
   533→    if (segments[2] === "agent" && segments[3]) return { kind: "workspace-agent-detail", workspaceId, agentId: decodePathPart(segments[3]), ...suffix };
   534→    if (segments[2] === "executor" && segments[3]) return { kind: "workspace-executor-detail", workspaceId, executorType: decodePathPart(segments[3]), ...suffix };
   535→    if (segments[2] === "web") {
   536→      const targetUrl = parsed.searchParams.get("url");
   537→      const title = parsed.searchParams.get("title");
   538→      if (targetUrl && title) {
   539→        return { kind: "workspace-web", workspaceId, url: targetUrl, title, sourcePageSlug: parsed.searchParams.get("source_page") ?? undefined, webId: parsed.searchParams.get("web_id") ?? undefined, hash: parsed.hash || undefined };
   540→      }
   541→    }
   542→    if (segments[2] === "page") {
   543→      const pageSlug = extractWorkspacePageSlug(pathname);
   544→      if (pageSlug) return { kind: "workspace-page", workspaceId, pageSlug, hash: parsed.hash || undefined };
   545→    }
   546→    const section = decodePathPart(segments[2]);
   547→    if (isWorkspaceSection(section)) return { kind: "workspace-section", workspaceId, section, ...suffix };
   548→  }
   549→
   550→  if (pathname === "/") return null;
   551→  return { kind: "global-route", path: `${pathname}${parsed.search}${parsed.hash}` };
   552→}
